/**
 * InformatikaLab - Lokal Offline Diagramma Tizimi (Chart.js alternativi)
 * Tashqi tarmoqsiz mustaqil ishlaydi, Bar va Line diagrammalarni xatosiz chizadi.
 */
class Chart {
  constructor(ctx, config) {
    this.ctx = ctx instanceof HTMLCanvasElement ? ctx.getContext('2d') : (ctx && ctx.getContext ? ctx.getContext('2d') : ctx);
    this.canvas = this.ctx ? this.ctx.canvas : null;
    this.config = config || {};
    this.type = this.config.type || 'bar';
    this.data = this.config.data || { labels: [], datasets: [] };
    this.options = this.config.options || {};

    if (this.canvas) {
      this.render();
      this._resizeHandler = () => this.render();
      window.addEventListener('resize', this._resizeHandler);
    }
  }

  destroy() {
    if (this._resizeHandler) {
      window.removeEventListener('resize', this._resizeHandler);
    }
    if (this.ctx && this.canvas) {
      this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    }
  }

  update() {
    this.render();
  }

  render() {
    if (!this.canvas || !this.ctx) return;

    const canvas = this.canvas;
    const ctx = this.ctx;
    const parent = canvas.parentElement;

    // Konteyner o'lchamini hisoblash
    const parentWidth = parent ? parent.clientWidth : (canvas.clientWidth || 500);
    const parentHeight = parent ? parent.clientHeight : (canvas.clientHeight || 260);

    const width = Math.max(parentWidth, 300);
    const height = Math.max(parentHeight, 220);

    // Retina (HiDPI) ekranni qo'llab-quvvatlash va o'lcham buzilishini oldini olish
    const dpr = window.devicePixelRatio || 1;
    canvas.width = Math.round(width * dpr);
    canvas.height = Math.round(height * dpr);
    canvas.style.width = width + 'px';
    canvas.style.height = height + 'px';

    ctx.save();
    ctx.scale(dpr, dpr);
    ctx.clearRect(0, 0, width, height);

    const labels = this.data.labels || [];
    const datasets = this.data.datasets || [];

    if (datasets.length === 0 || labels.length === 0) {
      ctx.fillStyle = '#64748b';
      ctx.font = '13px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText("Ma'lumotlar mavjud emas", width / 2, height / 2);
      ctx.restore();
      return;
    }

    const padding = { top: 35, right: 25, bottom: 40, left: 50 };
    const chartW = width - padding.left - padding.right;
    const chartH = height - padding.top - padding.bottom;

    if (chartW <= 0 || chartH <= 0) {
      ctx.restore();
      return;
    }

    // Eng katta qiymatni aniqlash
    let maxVal = 0;
    datasets.forEach(ds => {
      (ds.data || []).forEach(val => {
        const num = parseFloat(val) || 0;
        if (num > maxVal) maxVal = num;
      });
    });

    if (maxVal <= 0) maxVal = 10;
    // Y-o'qi bo'linmalari chiroyli butun yoki o'nlik bo'lishi
    const niceMax = Math.ceil(maxVal * 1.25 * 10) / 10;

    // Y o'qi panjara chiziqlari (Grid)
    ctx.strokeStyle = '#f1f5f9';
    ctx.lineWidth = 1;
    ctx.fillStyle = '#64748b';
    ctx.font = '11px sans-serif';
    ctx.textAlign = 'right';

    const steps = 4;
    for (let i = 0; i <= steps; i++) {
      const yVal = (niceMax / steps) * i;
      const yPos = padding.top + chartH - (i / steps) * chartH;
      ctx.beginPath();
      ctx.moveTo(padding.left, yPos);
      ctx.lineTo(padding.left + chartW, yPos);
      ctx.stroke();
      ctx.fillText(yVal.toFixed(1), padding.left - 8, yPos + 4);
    }

    // X o'qi pastki chizig'i
    ctx.strokeStyle = '#cbd5e1';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(padding.left, padding.top + chartH);
    ctx.lineTo(padding.left + chartW, padding.top + chartH);
    ctx.stroke();

    const count = labels.length;
    const stepX = chartW / count;

    // X o'qi yorliqlari (Kun nomlari)
    ctx.textAlign = 'center';
    ctx.fillStyle = '#334155';
    ctx.font = '11px sans-serif';
    labels.forEach((lbl, idx) => {
      const x = padding.left + idx * stepX + stepX / 2;
      ctx.fillText(lbl, x, padding.top + chartH + 20);
    });

    // Har bir datasetni chizish
    datasets.forEach((dataset, dIdx) => {
      const data = dataset.data || [];
      const color = dataset.backgroundColor || (dIdx === 0 ? '#0d9488' : '#3b82f6');
      const borderColor = dataset.borderColor || (dIdx === 0 ? '#0f766e' : '#1d4ed8');

      if (this.type === 'line') {
        // Line chart
        const points = [];
        data.forEach((val, idx) => {
          const num = parseFloat(val) || 0;
          const x = padding.left + idx * stepX + stepX / 2;
          const y = padding.top + chartH - (num / niceMax) * chartH;
          points.push({ x, y, num });
        });

        if (points.length > 0) {
          // Mayin maydon foni (Area gradient)
          if (points.length > 1) {
            ctx.save();
            ctx.beginPath();
            ctx.moveTo(points[0].x, points[0].y);
            for (let i = 1; i < points.length; i++) {
              ctx.lineTo(points[i].x, points[i].y);
            }
            ctx.lineTo(points[points.length - 1].x, padding.top + chartH);
            ctx.lineTo(points[0].x, padding.top + chartH);
            ctx.closePath();

            const areaGrad = ctx.createLinearGradient(0, padding.top, 0, padding.top + chartH);
            areaGrad.addColorStop(0, 'rgba(13, 148, 136, 0.22)');
            areaGrad.addColorStop(1, 'rgba(13, 148, 136, 0.01)');
            ctx.fillStyle = areaGrad;
            ctx.fill();
            ctx.restore();
          }

          // Asosiy chiziq
          ctx.save();
          ctx.strokeStyle = borderColor;
          ctx.lineWidth = 2.5;
          ctx.lineJoin = 'round';
          ctx.lineCap = 'round';
          ctx.beginPath();
          ctx.moveTo(points[0].x, points[0].y);
          for (let i = 1; i < points.length; i++) {
            ctx.lineTo(points[i].x, points[i].y);
          }
          ctx.stroke();
          ctx.restore();

          // Nuqtalar va qiymat yorliqlari
          points.forEach(p => {
            // Nuqta doirasi
            ctx.save();
            ctx.beginPath();
            ctx.arc(p.x, p.y, 4.5, 0, Math.PI * 2);
            ctx.fillStyle = '#ffffff';
            ctx.fill();
            ctx.strokeStyle = borderColor;
            ctx.lineWidth = 2.5;
            ctx.stroke();
            ctx.restore();

            // Qiymat matni
            ctx.save();
            ctx.fillStyle = '#0f172a';
            ctx.font = 'bold 11px sans-serif';
            ctx.textAlign = 'center';
            ctx.fillText(p.num.toFixed(1), p.x, p.y - 8);
            ctx.restore();
          });
        }
      } else {
        // Bar chart
        const dsCount = datasets.length;
        const totalBarW = Math.min(stepX * 0.65, 45);
        const barW = totalBarW / dsCount;

        data.forEach((val, idx) => {
          const num = parseFloat(val) || 0;
          const barH = (num / niceMax) * chartH;
          const x = padding.left + idx * stepX + (stepX - totalBarW) / 2 + dIdx * barW;
          const y = padding.top + chartH - barH;

          ctx.save();
          ctx.fillStyle = Array.isArray(color) ? (color[idx] || '#0d9488') : color;
          
          // Yumaloqlangan ustun tepasi
          const r = Math.min(4, barH / 2);
          ctx.beginPath();
          ctx.moveTo(x, y + barH);
          ctx.lineTo(x, y + r);
          ctx.quadraticCurveTo(x, y, x + r, y);
          ctx.lineTo(x + barW - 2 - r, y);
          ctx.quadraticCurveTo(x + barW - 2, y, x + barW - 2, y + r);
          ctx.lineTo(x + barW - 2, y + barH);
          ctx.closePath();
          ctx.fill();
          ctx.restore();

          // Qiymat matni
          ctx.save();
          ctx.fillStyle = '#0f172a';
          ctx.font = 'bold 10px sans-serif';
          ctx.textAlign = 'center';
          ctx.fillText(num.toFixed(1), x + (barW - 2) / 2, y - 5);
          ctx.restore();
        });
      }
    });

    // Legenda (Yuqoridagi ko'rsatkich)
    let legendX = padding.left;
    const legendY = 16;
    datasets.forEach((ds, idx) => {
      const c = Array.isArray(ds.backgroundColor) ? ds.backgroundColor[0] : (ds.backgroundColor || '#0d9488');
      ctx.fillStyle = c;
      ctx.fillRect(legendX, legendY - 8, 12, 10);
      ctx.fillStyle = '#334155';
      ctx.font = 'bold 11px sans-serif';
      ctx.textAlign = 'left';
      ctx.fillText(ds.label || `Ma'lumot ${idx + 1}`, legendX + 16, legendY);
      legendX += ctx.measureText(ds.label || `Ma'lumot ${idx + 1}`).width + 30;
    });

    ctx.restore();
  }
}

window.Chart = Chart;
